import socket
import requests

def get_geolocation_info(hostname):
    try:
        # Resolve the hostname to an IP address
        ip_address = socket.gethostbyname(hostname)
        print(f"Resolved IP address: {ip_address}")

        # Use the IP address to fetch geolocation data
        response = requests.get(f"https://ipinfo.io/{ip_address}/json")

        # Check if the request was successful
        response.raise_for_status()

        # Parse the JSON response
        geolocation_data = response.json()
        return geolocation_data

    except socket.gaierror:
        return {"error": "Invalid hostname or unable to resolve the hostname."}
    except requests.ConnectionError:
        return {"error": "Network problem or unable to connect to the geolocation service."}
    except requests.HTTPError as http_err:
        return {"error": f"HTTP error occurred: {http_err}"}
    except requests.RequestException as req_err:
        return {"error": f"An error occurred while fetching geolocation data: {req_err}"}
    except Exception as e:
        return {"error": f"An unexpected error occurred: {str(e)}"}

# Example usage
