import requests
import socket
import json
from typing import Dict, Optional, Union

def get_geolocation_by_hostname(hostname: str, timeout: int = 10) -> Optional[Dict[str, Union[str, Dict]]]:
    """
    Resolve hostname to IP address and fetch geolocation information from ipinfo.io.

    Args:
        hostname: The hostname to resolve and get geolocation for
        timeout: Request timeout in seconds (default: 10)

    Returns:
        Dictionary containing geolocation information if successful, None if failed
        Returns error information in case of failure with 'error' key

    Raises:
        ValueError: If hostname is empty or invalid
    """
