    if not hostname or not isinstance(hostname, str):
        raise ValueError("Hostname must be a non-empty string")

    hostname = hostname.strip()
    if not hostname:
        raise ValueError("Hostname cannot be empty or whitespace only")

    result = {}

    try:
        # Step 1: Resolve hostname to IP address
        try:
            # Get all IP addresses for the hostname
            ip_addresses = socket.getaddrinfo(hostname, None)
            # Extract the first IPv4 or IPv6 address
            ip_address = None
            for addr_info in ip_addresses:
                if addr_info[0] in (socket.AF_INET, socket.AF_INET6):
                    ip_address = addr_info[4][0]
                    break

            if not ip_address:
                return {"error": f"Could not resolve hostname '{hostname}' to an IP address"}

            result["resolved_ip"] = ip_address

        except socket.gaierror as e:
            return {"error": f"DNS resolution failed for '{hostname}': {str(e)}"}
        except Exception as e:
            return {"error": f"Unexpected error during DNS resolution: {str(e)}"}

        # Step 2: Fetch geolocation information from ipinfo.io
        try:
            url = f"https://ipinfo.io/{ip_address}/json"
            headers = {
                "User-Agent": "Python-Geolocation-Client/1.0",
                "Accept": "application/json"
            }

            response = requests.get(url, headers=headers, timeout=timeout)
            response.raise_for_status()  # Raise exception for bad status codes

            geolocation_data = response.json()

            # Merge the geolocation data with our result
            result.update(geolocation_data)

        except requests.exceptions.Timeout:
            return {"error": f"Request to ipinfo.io timed out after {timeout} seconds"}
        except requests.exceptions.ConnectionError:
            return {"error": "Network connection error - cannot reach ipinfo.io"}
        except requests.exceptions.HTTPError as e:
            if response.status_code == 404:
                return {"error": f"IP address {ip_address} not found in ipinfo.io database"}
            else:
                return {"error": f"HTTP error from ipinfo.io: {response.status_code} - {str(e)}"}
        except requests.exceptions.RequestException as e:
            return {"error": f"Request error: {str(e)}"}
        except json.JSONDecodeError:
            return {"error": "Invalid JSON response from ipinfo.io"}
        except Exception as e:
            return {"error": f"Unexpected error during geolocation request: {str(e)}"}

        return result

    except Exception as e:
        return {"error": f"Unexpected overall error: {str(e)}"}

