    # Test with various cases
    test_cases = [
        "google.com",           # Valid hostname
        "invalid-hostname-xyz", # Invalid hostname
        "8.8.8.8",             # Direct IP address
        "",                    # Empty string
        "     ",               # Whitespace only
    ]

    for hostname in test_cases:
        print(f"\nTesting: '{hostname}'")
        try:
            result = get_geolocation_by_hostname(hostname)
            if "error" in result:
