import socket
import ipaddress
import requests
from requests.exceptions import RequestException, Timeout, ConnectionError
from typing import Dict, Any, Optional


def resolve_and_get_geolocation(host: str, timeout: float = 5.0, prefer_ipv4: bool = True) -> Dict[str, Any]:
    """
    Resolve the IP address of `host` and fetch geolocation info from ipinfo.io for that IP.

    Returns a dict with:
      - success: bool
      - ip: resolved IP address (when success)
      - geo: dict with ipinfo.io JSON response (when success)
      - resolved_ips: list of candidate IPs discovered (when available)
      - error: human-readable error message (when not success)
      - details: optional extra details (like exception info)

    Parameters:
      - host: hostname or IP (optionally with port for IPv4 like "example.com:80" or "1.2.3.4:80").
              IPv6 literal with port (like "[::1]:8080") is also handled.
      - timeout: network timeout in seconds for the HTTP request to ipinfo.io and socket resolution
      - prefer_ipv4: whether to prefer IPv4 addresses when multiple addresses are returned

    Notes:
      - Uses the public ipinfo.io API endpoint https://ipinfo.io/{ip}/json (no API key).
      - Be mindful of ipinfo rate limits for frequent calls.
    """
    if not host or not isinstance(host, str):
        return {"success": False, "error": "Host must be a non-empty string."}

    def _normalize_host(h: str) -> str:
        # Remove surrounding whitespace
        h = h.strip()

        # If form [IPv6]:port => extract inside brackets
        if h.startswith("[") and "]" in h:
            closing = h.index("]")
            candidate = h[1:closing]
            return candidate

        # If there is exactly one colon, it might be host:port for IPv4 or hostname
        if h.count(":") == 1:
            # split off port
            host_part = h.split(":", 1)[0]
            return host_part

        # Otherwise return as-is (covers IPv6 like "2001:db8::1" without brackets)
        return h

    original_host = host
    host = _normalize_host(host)

    # If it's already an IP, use it directly
    try:
        ip_obj = ipaddress.ip_address(host)
        resolved_ips = [str(ip_obj)]
    except Exception:
        # Not a plain IP literal; try DNS resolution
        try:
            # getaddrinfo may return duplicates; collect unique addresses
            addrinfos = socket.getaddrinfo(host, None)
            resolved_set = []
            for info in addrinfos:
                sockaddr = info[4]
                ip = sockaddr[0]
                if ip not in resolved_set:
                    resolved_set.append(ip)
            resolved_ips = resolved_set
            if not resolved_ips:
                return {"success": False, "error": f"DNS resolution succeeded but no addresses found for {original_host}."}
        except socket.gaierror as e:
            return {"success": False, "error": f"DNS resolution failed for host '{original_host}'.", "details": str(e)}
        except Exception as e:
            return {"success": False, "error": f"Unexpected error during DNS resolution for '{original_host}'.", "details": str(e)}

    # Choose an IP according to preference
    selected_ip: Optional[str] = None
    if len(resolved_ips) == 1:
        selected_ip = resolved_ips[0]
    else:
        # try to prefer IPv4 or IPv6
        ipv4_candidates = []
        ipv6_candidates = []
        for ip in resolved_ips:
            try:
                ip_obj = ipaddress.ip_address(ip)
                if ip_obj.version == 4:
                    ipv4_candidates.append(ip)
                else:
                    ipv6_candidates.append(ip)
            except Exception:
                # ignore unparsable entries
                continue
        if prefer_ipv4:
            selected_ip = ipv4_candidates[0] if ipv4_candidates else (ipv6_candidates[0] if ipv6_candidates else None)
        else:
            selected_ip = ipv6_candidates[0] if ipv6_candidates else (ipv4_candidates[0] if ipv4_candidates else None)

        if selected_ip is None and resolved_ips:
            # fallback to first
            selected_ip = resolved_ips[0]

    if not selected_ip:
        return {"success": False, "error": f"Could not determine an IP address for host '{original_host}'.", "resolved_ips": resolved_ips}

    # Validate final IP
    try:
        ipaddress.ip_address(selected_ip)
    except Exception as e:
        return {"success": False, "error": f"Resolved value '{selected_ip}' is not a valid IP address.", "details": str(e), "resolved_ips": resolved_ips}

    # Query ipinfo.io
    url = f"https://ipinfo.io/{selected_ip}/json"
    headers = {"User-Agent": "resolve-and-geolocate/1.0 (+https://example)"}  # harmless UA

    try:
        resp = requests.get(url, headers=headers, timeout=timeout)
    except Timeout as e:
        return {"success": False, "error": "Request to geolocation service timed out.", "details": str(e), "ip": selected_ip, "resolved_ips": resolved_ips}
    except ConnectionError as e:
        return {"success": False, "error": "Network connection error while contacting geolocation service.", "details": str(e), "ip": selected_ip, "resolved_ips": resolved_ips}
    except RequestException as e:
        return {"success": False, "error": "Error while making request to geolocation service.", "details": str(e), "ip": selected_ip, "resolved_ips": resolved_ips}

    # Check HTTP status
    if resp.status_code != 200:
        # try to extract JSON error message if present
        try:
            err_json = resp.json()
            msg = err_json.get("error") or err_json
        except Exception:
            msg = resp.text[:500] if resp.text else f"HTTP {resp.status_code}"
        return {
            "success": False,
            "error": f"Geolocation service returned HTTP {resp.status_code}.",
            "details": msg,
            "ip": selected_ip,
            "resolved_ips": resolved_ips,
        }

    # Parse JSON
    try:
        data = resp.json()
    except ValueError as e:
        return {"success": False, "error": "Failed to parse JSON from geolocation service.", "details": str(e), "ip": selected_ip, "resolved_ips": resolved_ips}

    # Successful result
    return {"success": True, "ip": selected_ip, "geo": data, "resolved_ips": resolved_ips}

