def veg_stats_from_preferences(preferences, seed=None):
    """
    Given a dictionary mapping people -> vegetable(s), return statistics about vegetables.

    - preferences: dict where keys are person names and values are a vegetable string or
      an iterable (list/tuple/set) of vegetable strings.
    - seed: optional int to make the random counts reproducible.

    Returns a tuple: (df, veg_to_people, veg_to_person)
    - df: pandas DataFrame with columns ['vegetable', 'count', 'percentage', 'people']
      sorted by percentage descending.
    - veg_to_people: dict mapping each vegetable -> list of people who listed it.
    - veg_to_person: dict mapping each vegetable -> a single person (one of those who listed it).

    Random counts between 1 and 10 (inclusive) are assigned to each vegetable to simulate popularity/availability.
    Percentages are computed as count / sum(counts) * 100.
    """
    import random
    import pandas as pd

    if seed is not None:
        random.seed(seed)

    # Normalize input: ensure each value is a list of vegetables
    normalized = {}
