import json

def export_function_specs(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV file at `file_path`.
    The CSV columns:
    - 'Function Name'
    - 'Number of Arguments'
    - 'Defaults' (JSON string mapping parameter name -> repr(default))
    - 'Annotations' (JSON string mapping parameter name and 'return' -> repr(annotation))
    - 'Is Lambda' (bool)
    """
    def _ann_to_str(a):
        if a is inspect._empty:
            return None
        try:
            # for classes/types, prefer the short name
            if isinstance(a, type):
                return a.__name__
            return repr(a)
        except Exception:
            return str(a)

    rows = []
    for f in f_list:
        name = getattr(f, "__name__", repr(f))
        is_lambda = name == "<lambda>"
        defaults = {}
        annotations = {}
        num_args = None

        if not callable(f):
            # not a callable object
            num_args = None
        else:
            try:
                sig = inspect.signature(f)
                params = sig.parameters
                num_args = len(params)
                for pname, p in params.items():
                    if p.default is not inspect._empty:
                        try:
                            defaults[pname] = repr(p.default)
                        except Exception:
                            defaults[pname] = str(p.default)
                    if p.annotation is not inspect._empty:
                        annotations[pname] = _ann_to_str(p.annotation)
                if sig.return_annotation is not inspect._empty:
                    annotations['return'] = _ann_to_str(sig.return_annotation)
            except (ValueError, TypeError):
                # Some callables (builtins, C functions, etc.) may not expose a signature
                num_args = None

        # Serialize dicts as JSON strings for CSV storage
        defaults_str = json.dumps(defaults, ensure_ascii=False)
        annotations_str = json.dumps(annotations, ensure_ascii=False)

        rows.append({
            "Function Name": name,
            "Number of Arguments": num_args,
            "Defaults": defaults_str,
            "Annotations": annotations_str,
            "Is Lambda": bool(is_lambda)
