        "Function Name", "Number of Arguments", "Defaults", "Annotations", "Is Lambda"
    ])
    df.to_csv(file_path, index=False)

Here's a single self-contained Python function that uses requests to fetch a GitHub user's data, normalizes all string data (including keys) to ASCII, and returns the normalized dictionary. It handles nested structures (dicts/lists) and raises HTTP errors for non-200 responses.

```python
def fetch_github_user_ascii(username, timeout=10):
    """
    Retrieve GitHub user info for `username`, normalize all string data to ASCII,
    and return the normalized dictionary.

    Uses the requests library. Raises requests.HTTPError on non-2xx responses
    or other requests exceptions for network errors.

    Example:
        data = fetch_github_user_ascii('octocat')
    """
    import requests
    import unicodedata

    def to_ascii_text(s):
        # Normalize Unicode to NFKD, drop non-ASCII bytes
        return unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('ascii')

    def normalize(obj):
        # Recursively normalize strings in dicts and lists
        if isinstance(obj, str):
            return to_ascii_text(obj)
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_key = to_ascii_text(k) if isinstance(k, str) else k
                new[new_key] = normalize(v)
            return new
        if isinstance(obj, list):
            return [normalize(item) for item in obj]
        # leave numbers, booleans, None, etc. unchanged
        return obj

    url = f"https://api.github.com/users/{username}"
    headers = {
        'Accept': 'application/vnd.github.v3+json',
        'User-Agent': 'python-requests/urllib3'
    }

    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()  # raise on 4xx/5xx

    data = resp.json()
    return normalize(data)
```

Notes:
- If you expect many requests or private data, consider supplying authentication (Personal Access Token) via headers to increase rate limits.
- This function strips non-ASCII characters; if you prefer to preserve or transliterate differently, adjust the to_ascii_text function.

import requests
import unicodedata
from typing import Any, Dict, Optional

def get_github_user_ascii(username: str, timeout: Optional[float] = 10.0) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username` and normalize all string data to ASCII.

    - Uses the GitHub public REST API: https://api.github.com/users/{username}
    - Normalizes strings using NFKD and strips non-ASCII characters.
    - Recursively processes dicts and lists so all string values and keys become ASCII-only.

    Parameters:
    - username: GitHub username to look up.
    - timeout: optional request timeout in seconds (default 10s).

    Returns:
    - A dictionary with the same structure as the API JSON, but with all strings normalized to ASCII.

    Raises:
    - ValueError if the user is not found (HTTP 404).
    - RuntimeError for network/HTTP errors.
    """
    def _normalize(obj: Any) -> Any:
        """Recursively normalize strings in obj to ASCII, preserving other types."""
        if isinstance(obj, str):
            # Normalize to NFKD form, then remove non-ASCII bytes
            return unicodedata.normalize("NFKD", obj).encode("ascii", "ignore").decode("ascii")
        elif isinstance(obj, dict):
            # Normalize keys (they are strings in JSON) and values
            normalized_dict = {}
            for k, v in obj.items():
                norm_key = _normalize(k) if isinstance(k, str) else k
                normalized_dict[norm_key] = _normalize(v)
            return normalized_dict
        elif isinstance(obj, list):
            return [_normalize(item) for item in obj]
        else:
            # numbers, booleans, None, etc.
            return obj

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json", "User-Agent": "requests-python-client"}

    try:
        resp = requests.get(url, headers=headers, timeout=timeout)
    except requests.RequestException as exc:
        raise RuntimeError(f"Network error while contacting GitHub API: {exc}") from exc

    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")

    try:
        resp.raise_for_status()
    except requests.HTTPError as exc:
        raise RuntimeError(f"GitHub API returned HTTP error {resp.status_code}: {exc}") from exc

    try:
        data = resp.json()
    except ValueError as exc:
        raise RuntimeError("Failed to parse JSON response from GitHub API.") from exc

    return _normalize(data)

