# normalized = get_github_user_ascii("torvalds")
# print(normalized["name"], normalized["bio"])

Here's a self-contained Python function that uses NumPy to compute the median of all elements in a nested list (handles arbitrarily nested lists/tuples/ndarrays). It flattens the input recursively, converts to a numeric NumPy array, and returns the median as a Python float.

```python
def median_nested(L):
    """
    Compute the median of all numeric elements in a nested list/tuple/ndarray L.
    Uses numpy for the median calculation.
    Raises ValueError for empty input or if elements cannot be converted to floats.
    """
    import numpy as np

    def _iter_flat(x):
        if isinstance(x, (list, tuple, np.ndarray)):
            for item in x:
                yield from _iter_flat(item)
        else:
            yield x

    flat = list(_iter_flat(L))
    if len(flat) == 0:
        raise ValueError("Input nested list is empty; median undefined.")

    try:
        arr = np.array(flat, dtype=float)
    except Exception as e:
        raise ValueError("Could not convert elements to numeric values.") from e

    return float(np.median(arr))

# Example:
# median_nested([[1, 2], [3, [4, 5]]])  -> 3.0
```

