import numpy as np

def median_of_nested(L):
    """
    Compute the median of all numeric elements in a nested list/tuple/ndarray `L`.
    Uses numpy for the median calculation. Returns a float.
    Raises ValueError if no elements are found.
    """
    def _flatten(x):
        # recurse into lists, tuples and numpy arrays; treat other objects as scalars
        if isinstance(x, (list, tuple, np.ndarray)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    flat = list(_flatten(L))
    if len(flat) == 0:
        raise ValueError("no elements to compute median")
    arr = np.array(flat, dtype=float)   # convert to numeric type
    return float(np.median(arr))

# Example:
# median_of_nested([[1, 2, [3]], 4, (5, 6)])  -> 3.5

def iqr_nested(L):
    """
    Calculate the interquartile range (IQR = Q3 - Q1) of all numeric elements
    contained anywhere in a nested list/tuple/set/ndarray structure L.

    Uses scipy.stats.iqr and ignores NaNs (they are omitted). Raises ValueError
    if no numeric values are found and TypeError if a non-numeric, non-iterable
    element is encountered.

    Example:
        iqr_nested([[1, 2, [3, 4]], (5, 6)])  -> 3.0  (Q3=5.0, Q1=2.0)
    """
    from numbers import Number
    import numpy as np
    from scipy.stats import iqr

    def _flatten(obj):
        # Recursively yield all non-iterable items. Handles list/tuple/set/ndarray.
        if isinstance(obj, (list, tuple, set)):
            for item in obj:
                yield from _flatten(item)
        elif isinstance(obj, np.ndarray):
            for item in obj.ravel():
                yield from _flatten(item)
        else:
            yield obj

    values = []
    for item in _flatten(L):
        # Exclude booleans (they are instances of Number) unless you want to treat
        # True/False as 1/0 in the numeric set.
        if isinstance(item, bool):
            continue
        if isinstance(item, Number):
            values.append(float(item))
        else:
            # If item is an iterable-like object that wasn't caught above, it will
            # be yielded as-is; treat non-numeric items as an error.
            raise TypeError(f"Non-numeric element encountered: {item!r}")

    if len(values) == 0:
        raise ValueError("No numeric values found in the nested input")

    # Use scipy.stats.iqr, omitting NaNs if any
    return float(iqr(values, axis=None, nan_policy='omit'))

Here's a self-contained Python function that uses numpy to find the most common value in each column of a CSV file with column names. Ties are broken by alphabetical order (the first alphabetically is chosen). If the CSV is empty (no data rows), an empty dictionary is returned.

```python
def most_common_per_column(csv_path):
    """
    Return a dict mapping column name -> most common value for each column in the CSV at csv_path.
    If multiple values tie for most common, the alphabetically first (lexicographic) is chosen.
    If the CSV is empty (no data rows) or cannot be parsed, return {}.

    Uses numpy for loading and counting.
    """
    import numpy as np
    import os

    if not os.path.exists(csv_path):
        raise FileNotFoundError(f"No such file: {csv_path}")

    try:
        # Read CSV with header names; keep all data as strings and strip whitespace
        data = np.genfromtxt(csv_path, delimiter=',', names=True, dtype=None,
                             encoding='utf-8', autostrip=True)
    except Exception:
        # e.g., empty file or no columns to parse
        return {}

    # If there are no data rows, return empty dict
    try:
        if hasattr(data, "size") and data.size == 0:
            return {}
    except Exception:
        return {}

    names = data.dtype.names
    if not names:
        return {}

    result = {}
    for name in names:
        col = data[name]
        # Ensure we have a 1-D array of strings (handles scalar/0-d cases)
        col_arr = np.atleast_1d(col).astype(str)
        if col_arr.size == 0:
            continue
        vals, counts = np.unique(col_arr, return_counts=True)
        # vals from np.unique are sorted lexicographically, so ties are resolved alphabetically
        max_count = counts.max()
        candidates = vals[counts == max_count]
        result[name] = candidates[0]
    return result
