Here's a self-contained Python function that uses numpy to read a CSV (with a header row) and returns the most common value for each column. If multiple values tie, the alphabetically first value is chosen. If an empty CSV is passed (no data rows or truly empty file), an empty dict is returned.

```python
import numpy as np
from typing import Dict, Union, IO

def most_common_per_column_csv(csv_source: Union[str, IO]) -> Dict[str, str]:
    """
    Read a CSV with column names and return a dict mapping each column name
    to its most common value. If multiple values tie for most common, the
    alphabetically first value is chosen. If the CSV is empty (no data rows
    or empty file), returns an empty dict.

    Parameters:
    - csv_source: filename (str) or file-like object

    Returns:
    - dict: {column_name: most_common_value}
    """
    try:
        data = np.genfromtxt(csv_source, delimiter=',', dtype=str, names=True,
                             autostrip=True, encoding='utf-8')
    except (ValueError, OSError):
        # ValueError can be "Empty input file" from genfromtxt, OSError for e.g. missing file
        return {}

    # If genfromtxt returned nothing or no column names, treat as empty
    if data is None:
        return {}
    if getattr(data, "dtype", None) is None or data.dtype.names is None:
        return {}
    # If there are no data rows (structured array of length 0), return empty
    if hasattr(data, "size") and data.size == 0:
        return {}

    result: Dict[str, str] = {}
    for col in data.dtype.names:
        col_vals = data[col]
        # If there's a single row, genfromtxt may return a 0-d void; wrap as 1-element array
        if np.ndim(col_vals) == 0:
            col_arr = np.array([str(col_vals)], dtype=str)
        else:
            col_arr = np.array(col_vals, dtype=str)

        # Compute unique values and counts. np.unique returns sorted unique values,
        # so ties are resolved by taking the first returned value (alphabetically first).
        uniques, counts = np.unique(col_arr, return_counts=True)
        # Pick the value(s) with maximum count
        max_count = counts.max()
        max_indices = np.where(counts == max_count)[0]
        chosen = uniques[max_indices[0]]
        result[col] = str(chosen)

    return result
```

