def summarize_xyz(d):
    """
    Calculate mean, sum, max, min and standard deviation for keys "x", "y", and "z"
    from a list of dictionaries `d`, using pandas.

    Args:
        d (list of dict): Input data, e.g. [{"x":1,"y":2,"z":3}, {"x":4,"y":5,"z":6}, ...]

    Returns:
        dict: Nested dict in the form
              {
                "x": {"mean": ..., "sum": ..., "max": ..., "min": ..., "std": ...},
                "y": {...},
                "z": {...}
              }
              Any statistic that cannot be computed (missing/non-numeric data) is returned as None.
              Note: std uses pandas' default (sample std, ddof=1).
    """
    import pandas as pd
    import numpy as np

    if not isinstance(d, (list, tuple)):
        raise TypeError("d must be a list (or tuple) of dictionaries")

    cols = ["x", "y", "z"]
    # Build DataFrame and ensure columns x,y,z exist (missing columns become NaN)
    df = pd.DataFrame(d).reindex(columns=cols)
    # Coerce non-numeric values to NaN
    df = df.apply(pd.to_numeric, errors="coerce")

    # Aggregate the required statistics
    agg = df.agg(["mean", "sum", "max", "min", "std"]).transpose()

    # Convert results to plain Python types and replace NaN with None
    result = {}
    for c in cols:
        if c in agg.index:
            row = agg.loc[c]
        else:
            row = pd.Series(index=["mean", "sum", "max", "min", "std"], dtype="float64")
        stats = {}
        for stat in ["mean", "sum", "max", "min", "std"]:
            val = row.get(stat, np.nan)
            if pd.isna(val):
                stats[stat] = None
            else:
                # convert numpy scalars to native Python types
                if isinstance(val, (np.generic,)):
                    val = val.item()
                stats[stat] = val
        result[c] = stats

    return result

