    if isinstance(json_data, str):
        try:
            json_data = json.loads(json_data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {e}")

    if not isinstance(json_data, dict):
        raise ValueError("JSON data must be a dictionary or valid JSON string")

    if not key_path:
        raise ValueError("key_path cannot be empty")

    # Navigate through the nested structure
    current = json_data
    for i, key in enumerate(key_path[:-1]):
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key '{key}' not found at path level {i}")

    # Extract the final level
    final_key = key_path[-1]

    # Handle case where the path leads to a list of objects
    if isinstance(current, list):
