def html_table_to_sqlite(
    source: str,
    sqlite_path: str,
    table_name: Optional[str] = None,
    table_index: Optional[Union[int, str]] = 0,
    table_xpath: Optional[str] = None,
    encoding: Optional[str] = None,
    include_header: bool = True,
    replace_table: bool = False,
    pk_columns: Optional[List[str]] = None,
    convert_types: bool = True,
    row_filter: Optional[Callable[[Dict[str, Any]], bool]] = None,
    verbose: bool = False,
) -> Dict[str, Any]:
    """
    Parse HTML table data from a URL or local file and store into an SQLite database.

    Parameters:
    - source: URL (http/https) or local file path.
    - sqlite_path: path to the SQLite database file.
    - table_name: if provided, name to use for the created table. If processing multiple tables (table_index=None or "all"),
                  this is used as a base and appended with an index.
    - table_index: which table to process:
        - integer (0-based) selects a specific table,
        - None or "all" processes all tables found,
        - default 0 selects the first table.
    - table_xpath: optional XPath expression to select table elements (overrides table_index).
    - encoding: optional text encoding to decode bytes (HTTP response or file). If None, best-effort is used.
    - include_header: if True, use the first header row (<th> or first <tr> if no <th>) to name columns.
    - replace_table: if True, drop existing table(s) before creating.
    - pk_columns: optional list of column names to make the PRIMARY KEY (for upsert behavior use INSERT OR REPLACE).
    - convert_types: if True, attempt simple type inference (INTEGER, REAL, TEXT) per column.
    - row_filter: optional callable that receives a dict (column->value) and returns True to include the row.
    - verbose: if True, prints progress information.

    Returns:
    - summary dict: { "tables_created": int, "rows_inserted": int, "details": {table_name: inserted_count, ...} }

    Notes:
    - Handles colspan by replicating cell value across the spanned columns. Rowspan is not fully supported.
    - Uses lxml library for HTML parsing.
    - Tries requests for HTTP; falls back to urllib if requests is unavailable.
    """

    def _log(*args):
        if verbose:
            print(*args)

    # ---------- Fetch content ----------
    def _fetch_source(s: str) -> str:
        # Determine if URL
        is_url = re.match(r"^https?://", s.strip(), re.I) is not None
        if is_url:
            if requests:
                resp = requests.get(s, timeout=20)
                resp.raise_for_status()
                content_bytes = resp.content
                enc = encoding or resp.encoding or "utf-8"
                try:
                    return content_bytes.decode(enc, errors="replace")
                except Exception:
                    return content_bytes.decode("utf-8", errors="replace")
            else:
                with urllib_request.urlopen(s, timeout=20) as f:
                    content_bytes = f.read()
                    enc = encoding or "utf-8"
                    return content_bytes.decode(enc, errors="replace")
        else:
            # local file
            with open(s, "rb") as f:
                content_bytes = f.read()
                enc = encoding or "utf-8"
                return content_bytes.decode(enc, errors="replace")

    html_text = _fetch_source(source)
    doc = lxml_html.fromstring(html_text)

    # ---------- Find table elements ----------
    if table_xpath:
        tables = doc.xpath(table_xpath)
    else:
        tables = doc.findall(".//table")

    if not tables:
        raise ValueError("No <table> elements found in the provided source.")

    # Determine which tables to process
    process_all = table_index in (None, "all")
    if not process_all:
        if not isinstance(table_index, int):
            # If table_index not int/default, treat as first table
            table_index = 0
        if table_index < 0 or table_index >= len(tables):
            raise IndexError(f"table_index {table_index} out of range (0..{len(tables)-1})")
        tables = [tables[table_index]]

    # ---------- Helpers for cell text and colspan ----------
    def _cell_text(cell):
        # get normalized text for a cell
        txt = "".join(cell.itertext())
        txt = html.unescape(txt).strip()
        # normalize whitespace
        txt = re.sub(r"\s+", " ", txt)
        return txt if txt != "" else None

    def _expand_cells(cells):
        # cells: list of lxml elements
        out = []
        for cell in cells:
            span = cell.get("colspan")
            try:
                n = int(span) if span else 1
            except Exception:
                n = 1
            text = _cell_text(cell)
            # replicate for colspan
            for _ in range(max(1, n)):
                out.append(text)
        return out

    # ---------- Table parsing ----------
    def _parse_table(tbl):
        # collect rows as lists of cell texts
        rows = []
        all_trs = tbl.findall(".//tr")
        if not all_trs:
            return [], []

        header_row = None
        header_cells = None

        # look for header: any <th> in the table? Use the first row that contains th
        if include_header:
            ths = tbl.findall(".//th")
            if ths:
                # Find first tr that contains th children
                for tr in all_trs:
                    th_children = tr.findall(".//th")
                    if th_children:
                        header_row = tr
                        header_cells = _expand_cells(th_children)
                        break
            if header_row is None:
                # fallback: use the first tr as header if it has same number of cells as subsequent rows
                first_tr = all_trs[0]
                td_children = first_tr.findall(".//td")
                th_children = first_tr.findall(".//th")
                if th_children:
                    header_row = first_tr
                    header_cells = _expand_cells(th_children)
                elif td_children:
                    # treat first row as header
                    header_row = first_tr
                    header_cells = _expand_cells(td_children)

        # Build data rows skipping the header_row if set
        for tr in all_trs:
            if header_row is not None and tr is header_row:
                continue
            tds = tr.findall(".//td")
            # ignore rows without td (could be an empty row)
            if not tds:
                continue
            expanded = _expand_cells(tds)
            rows.append(expanded)

        # normalize width: find max width among header and rows
        widths = [len(r) for r in rows]
        if header_cells:
            widths.append(len(header_cells))
        maxw = max(widths) if widths else 0

        # pad
        if header_cells:
            header_cells = header_cells + [None] * (maxw - len(header_cells))
        else:
            header_cells = [None] * maxw

        padded_rows = []
        for r in rows:
            padded_rows.append(r + [None] * (maxw - len(r)))

        return header_cells, padded_rows

    # ---------- Sanitize column and table names ----------
    def _sanitize_identifier(name: str) -> str:
        if not name:
            return ""
        # convert to ascii-limited safe name
        name = name.strip()
        # lower-case and replace non-alphanumeric with underscore
        name = re.sub(r"\s+", "_", name)
        name = re.sub(r"[^0-9a-zA-Z_]", "_", name)
        # ensure doesn't start with digit
        if re.match(r"^\d", name):
            name = "_" + name
        return name.lower()

    def _unique_column_names(names: List[Optional[str]]) -> List[str]:
        out = []
        seen = {}
        for i, n in enumerate(names):
            if n:
                base = _sanitize_identifier(n)
                if not base:
                    base = f"col{i+1}"
            else:
                base = f"col{i+1}"
            candidate = base
            k = 1
            while candidate in seen:
                candidate = f"{base}_{k}"
                k += 1
            seen[candidate] = True
            out.append(candidate)
        return out

    def _table_sql_name(base: Optional[str], idx: int) -> str:
        if base:
            sanitized = _sanitize_identifier(base)
            if idx is not None:
                return f"{sanitized}_{idx}"
            else:
                return sanitized
        else:
            if idx is not None:
                return f"html_table_{idx}"
            else:
                return "html_table"

    # ---------- Type inference ----------
    int_re = re.compile(r"^[+-]?\d+$")
    float_re = re.compile(r"^[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?$")

    def _is_int(s: str) -> bool:
        if s is None:
            return False
        s = s.strip().replace(",", "")  # remove thousands separators
        return bool(int_re.match(s))

    def _is_float(s: str) -> bool:
        if s is None:
            return False
        s = s.strip().replace(",", "")
        if _is_int(s):
            return True  # ints are also valid floats
        return bool(float_re.match(s))

    def _infer_column_types(rows: List[List[Optional[str]]]) -> List[str]:
        if not rows:
            return []
        ncols = max(len(r) for r in rows)
        types = []
        for c in range(ncols):
            vals = [r[c] for r in rows if c < len(r) and r[c] not in (None, "")]
            if not vals:
                types.append("TEXT")
                continue
            if all(_is_int(v) for v in vals):
                types.append("INTEGER")
            elif all(_is_float(v) for v in vals):
                types.append("REAL")
            else:
                types.append("TEXT")
        return types

    # ---------- SQLite interaction ----------
    conn = sqlite3.connect(sqlite_path)
    cur = conn.cursor()
    created_tables = 0
    total_inserted = 0
    details = {}

    try:
        for idx, tbl in enumerate(tables):
            h_cells, data_rows = _parse_table(tbl)

            # set table name for this table
            tbl_sql_name = None
            if process_all:
                base = table_name or (_sanitize_identifier(tbl.get("id") or tbl.get("name") or tbl.get("class") or f"table"))
                tbl_sql_name = _table_sql_name(base, idx)
            else:
                tbl_sql_name = _table_sql_name(table_name, None) if table_name else _table_sql_name(None, 0)

            # sanitize and create column names
            col_names = _unique_column_names(h_cells)
            if not any(col_names):
                # degenerate case: create generic columns based on row width
                maxw = max((len(r) for r in data_rows), default=0)
                col_names = [f"col{i+1}" for i in range(maxw)]

            # ensure pk_columns are valid and sanitized
            if pk_columns:
                pk_sanitized = [_sanitize_identifier(c) for c in pk_columns]
                # ensure pk exists in col_names
                for pk in pk_sanitized:
                    if pk not in col_names:
                        raise ValueError(f"Primary key column '{pk}' not found among parsed columns: {col_names}")
            else:
                pk_sanitized = None

            # infer types
            col_types = _infer_column_types(data_rows) if convert_types else ["TEXT"] * len(col_names)
            # ensure alignment length
            if len(col_types) < len(col_names):
                col_types += ["TEXT"] * (len(col_names) - len(col_types))

            # prepare CREATE TABLE statement
            # Build column definitions, optionally with PRIMARY KEY
            col_defs = []
            for name, typ in zip(col_names, col_types):
                # safe quoting of identifier by using double quotes; values are sanitized earlier
                if pk_sanitized and name in pk_sanitized and len(pk_sanitized) == 1:
                    # single column primary key inline
                    col_defs.append(f'"{name}" {typ} PRIMARY KEY')
                else:
                    col_defs.append(f'"{name}" {typ}')
            if pk_sanitized and len(pk_sanitized) > 1:
                # table-level primary key constraint
                pk_clause = f", PRIMARY KEY ({', '.join('\"' + pk + '\"' for pk in pk_sanitized)})"
            else:
                pk_clause = ""

            if replace_table:
                cur.execute(f'DROP TABLE IF EXISTS "{tbl_sql_name}"')
                conn.commit()

            # create table if not exists
            create_sql = f'CREATE TABLE IF NOT EXISTS "{tbl_sql_name}" ({", ".join(col_defs)}{pk_clause})'
            _log("Creating table with SQL:", create_sql)
            cur.execute(create_sql)
            created_tables += 1

            # prepare insert statement
            placeholders = ", ".join("?" for _ in col_names)
            cols_quoted = ", ".join(f'"{c}"' for c in col_names)
            # Use INSERT OR REPLACE if primary key(s) exist, to allow upsert-like behavior
            if pk_sanitized:
                insert_sql = f'INSERT OR REPLACE INTO "{tbl_sql_name}" ({cols_quoted}) VALUES ({placeholders})'
            else:
                insert_sql = f'INSERT INTO "{tbl_sql_name}" ({cols_quoted}) VALUES ({placeholders})'

            # prepare rows transformed to match types and columns
            to_insert = []
            for r in data_rows:
                # pad row
                padded = r + [None] * (len(col_names) - len(r))
                # build dict for row_filter
                row_dict = {col_names[i]: (padded[i] if padded[i] is not None else None) for i in range(len(col_names))}
                if row_filter and not row_filter(row_dict):
                    continue

                # convert values to Python types according to inferred col_types
                row_vals = []
                for val, typ in zip(padded, col_types):
                    if val is None or val == "":
                        row_vals.append(None)
                        continue
                    if convert_types and typ == "INTEGER":
                        try:
                            row_vals.append(int(val.strip().replace(",", "")))
                        except Exception:
                            row_vals.append(val)
                    elif convert_types and typ == "REAL":
                        try:
                            row_vals.append(float(val.strip().replace(",", "")))
                        except Exception:
                            row_vals.append(val)
                    else:
                        row_vals.append(val)
                to_insert.append(tuple(row_vals))

            # Insert rows in a transaction
            inserted = 0
            if to_insert:
                cur.executemany(insert_sql, to_insert)
                inserted = cur.rowcount if cur.rowcount != -1 else len(to_insert)
                total_inserted += len(to_insert)
                details[tbl_sql_name] = len(to_insert)
            else:
                details[tbl_sql_name] = 0

            conn.commit()
            _log(f"Table '{tbl_sql_name}': inserted {details[tbl_sql_name]} rows")

    finally:
        cur.close()
        conn.close()

    return {"tables_created": created_tables, "rows_inserted": total_inserted, "details": details}

Here's a self-contained Python function that uses pytesseract + Pillow to open an image, run OCR, and attempt to normalize/convert the text encoding. If OCR yields nothing useful, it falls back to reading image comments/metadata (JPEG comments, PNG text fields, EXIF user comment fields). The function returns either the normalized text (default) or a (text, source) tuple indicating whether the result came from OCR or comments.

Notes:
- You must have Tesseract-OCR installed on your system and pytesseract + Pillow (PIL) installed in Python.
- Optionally pass the full path to the tesseract binary via tesseract_cmd if it's not on your PATH.

Function:

```
def extract_text_from_image(path, encodings=None, tesseract_cmd=None, lang=None, return_source=False):
    """
    Open an image file, run OCR via pytesseract, normalize/convert the text encoding,
    and if OCR yields nothing useful, fall back to extracting image comments/metadata.

    Parameters:
    - path (str): path to the image file.
    - encodings (list[str], optional): encodings to try when decoding bytes. Defaults to
      ['utf-8','utf-8-sig','cp1252','latin-1','utf-16'].
    - tesseract_cmd (str, optional): path to the tesseract binary (e.g. '/usr/bin/tesseract').
    - lang (str, optional): language(s) to pass to pytesseract (e.g. 'eng', 'eng+fra').
    - return_source (bool, optional): if True, return a tuple (text, source) where source
      is one of 'ocr', 'comment', or 'none'. If False (default), return text only.

    Returns:
    - str or (str, str): normalized text (and optionally the source).
    """
    import pytesseract
    from PIL import Image, ExifTags

    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    encodings = encodings or ['utf-8', 'utf-8-sig', 'cp1252', 'latin-1', 'utf-16']

    def printable_ratio(s):
        if not s:
            return 0.0
        total = len(s)
        printable = sum(1 for ch in s if ch.isprintable() and ch not in '\r\n\t')
        return printable / total if total else 0.0

    def normalize_text(obj):
        """
        Accept bytes or str. Try to decode/repair common mojibake scenarios and return a Unicode str.
        """
        if obj is None:
            return ''
        # If bytes, try listed decodings
        if isinstance(obj, (bytes, bytearray)):
            b = bytes(obj)
            for enc in encodings:
                try:
                    dec = b.decode(enc)
                    if printable_ratio(dec) > 0.4:
                        return dec
                except Exception:
                    continue
            # last resort: decode with 'latin-1' replacing errors
            try:
                return b.decode('latin-1', errors='replace')
            except Exception:
                return b.decode('utf-8', errors='replace')

        # If already str, try to detect & fix common mojibake by re-encoding/decoding
        if isinstance(obj, str):
            s = obj
            # If looks fine, return immediately
            if '�' not in s and printable_ratio(s) > 0.6:
                return s
            candidates = [s]
            # Try to reinterpret encoded bytes that were decoded with the wrong codec.
            for from_enc in ('latin-1', 'cp1252'):
                try:
                    b = s.encode(from_enc, errors='replace')
                except Exception:
                    continue
                for to_enc in ('utf-8', 'utf-8-sig', 'utf-16'):
                    try:
                        cand = b.decode(to_enc, errors='strict')
                        candidates.append(cand)
                    except Exception:
                        # ignore decode errors
                        pass
            # pick candidate with highest printable ratio
            best = max(candidates, key=printable_ratio)
            return best

        # Fallback: stringize
        try:
            return str(obj)
        except Exception:
            return ''

    # Open image
    try:
        img = Image.open(path)
    except Exception as e:
        raise IOError(f"Could not open image '{path}': {e}")

    # Try OCR first
    try:
        if lang:
            raw_ocr = pytesseract.image_to_string(img, lang=lang)
        else:
            raw_ocr = pytesseract.image_to_string(img)
    except Exception:
        raw_ocr = ''

    normalized = normalize_text(raw_ocr).strip()
    if normalized:
        return (normalized, 'ocr') if return_source else normalized

    # OCR returned nothing or garbage — fall back to image info/comments
    comments = []

    # Standard info dict (PNG tEXt/iTXt, JPEG comment maybe under 'comment')
    info = getattr(img, 'info', {})
    if isinstance(info, dict):
        for k, v in info.items():
            if v is None:
                continue
            # Some fields are bytes, some are str
            try:
                comments.append(normalize_text(v).strip())
            except Exception:
                try:
                    comments.append(str(v))
                except Exception:
                    pass

    # Try EXIF fields that commonly contain user comments
    try:
        exif = img.getexif()
        if exif:
            for tag_id, value in exif.items():
                tag = ExifTags.TAGS.get(tag_id, tag_id)
                if tag in ('UserComment', 'XPComment', 'ImageDescription', 'Comment'):
                    if value is None:
                        continue
                    comments.append(normalize_text(value).strip())
    except Exception:
        # Some image types / PIL versions may not support getexif; ignore
        pass

    # Consolidate comments
    comments = [c for c in comments if c]
    if comments:
        final = "\n".join(comments).strip()
        return (final, 'comment') if return_source else final

    # Nothing found
    return ('', 'none') if return_source else ''
