If you want more robust mojibake repair (fixing lots of weird encodings), consider adding the ftfy library (fixes text for you) or the chardet library to better detect encodings.

```python
def extract_text_from_image_with_fallback(image_path,
                                         target_encoding='utf-8',
                                         tesseract_lang=None,
                                         tesseract_config=''):
    """
    Open an image, try OCR with pytesseract, convert the extracted text to target_encoding.
    If OCR yields no usable text, try to extract textual comments/metadata from the image
    (EXIF UserComment, ImageDescription, PNG tEXt/iTXt chunks, etc.) and convert their encoding.

    Returns a tuple: (text, info) where:
      - text: final Unicode string (decoded/normalized to target_encoding; characters not representable
              in target_encoding are replaced).
      - info: dict with keys:
          - 'source': 'ocr' or 'comment' or 'none'
          - 'raw_encoding': encoding detected/assumed for the raw data (may be None)
          - 'raw_text': raw text obtained before conversion (str or bytes)
          - 'note': additional notes (e.g., error messages)

    Dependencies:
      - Pillow (PIL)
      - pytesseract (and Tesseract installed on the system)

    Example:
      text, info = extract_text_from_image_with_fallback('photo.jpg', target_encoding='utf-8')
    """
    from PIL import Image, ExifTags
    import pytesseract

    def _convert_to_target(s_or_b, tgt_enc):
        """
        Convert either str or bytes to a Unicode string normalized so that it can be
        represented in tgt_enc. Returns (unicode_string, detected_encoding_used_for_decoding).
        """
        # If we already have a Python str, ensure it's representable in target encoding
        if isinstance(s_or_b, str):
            try:
                # Encode to target with replace, then decode back to produce a string
                b = s_or_b.encode(tgt_enc, errors='replace')
                return b.decode(tgt_enc, errors='replace'), tgt_enc
            except Exception:
                # fallback: return original as-is
                return s_or_b, None

        # bytes: try several likely decodings in order
        if isinstance(s_or_b, (bytes, bytearray)):
            for enc in ('utf-8', 'utf-16', 'utf-16le', 'utf-16be', 'cp1252', 'latin-1'):
                try:
                    decoded = s_or_b.decode(enc)
                    # normalize to target encoding (replace any chars not representable)
                    b = decoded.encode(tgt_enc, errors='replace')
                    return b.decode(tgt_enc, errors='replace'), enc
                except Exception:
                    continue
            # last resort: latin-1 with replacement
            decoded = s_or_b.decode('latin-1', errors='replace')
            b = decoded.encode(tgt_enc, errors='replace')
            return b.decode(tgt_enc, errors='replace'), 'latin-1'
        # unknown type
        return str(s_or_b), None

    def _extract_image_comments(img):
        """
        Try to gather textual metadata from the image. Returns a list of (key, value)
        where value may be bytes or str.
        """
        comments = []

        # 1) PIL info dict (PNG tEXt/iTXt, JPEG comments sometimes appear here)
        try:
            info = getattr(img, 'info', {}) or {}
            for k, v in info.items():
                # Pillow sometimes stores PNG text chunks directly as str. Keep as-is.
                comments.append((f'info:{k}', v))
        except Exception:
            pass

        # 2) EXIF tags (JPEG/ TIFF). Use image.getexif() if available (Pillow >= 6)
        try:
            exif = None
            if hasattr(img, 'getexif'):
                exif = img.getexif()
            elif hasattr(img, '_getexif'):
                exif = img._getexif()
            if exif:
                # exif may be a dict-like mapping tag-id -> value
                # Map known tag IDs to names
                tag_name_map = {}
                try:
                    for tid, name in ExifTags.TAGS.items():
                        tag_name_map[tid] = name
                except Exception:
                    tag_name_map = {}

                for tid, val in dict(exif).items():
                    name = tag_name_map.get(tid, f'EXIF_{tid}')
                    # Common textual tags: ImageDescription (270), UserComment (37510),
                    # XPComment (40092), XPTitle (40091), XPAuthor (40093), XPKeywords (40094)
                    comments.append((f'exif:{name}', val))
        except Exception:
            pass

        # 3) JPEG COM marker: Pillow may expose as info['comment'] (bytes)
        # already handled above via img.info; but ensure presence
        try:
            if hasattr(img, 'info') and 'comment' in img.info:
                comments.append(('jpeg:comment', img.info.get('comment')))
        except Exception:
            pass

        return comments

    note = None
    raw_text = None
    raw_enc = None
    source = 'none'

    # 1) Try OCR
    try:
        with Image.open(image_path) as img:
            try:
                # pytesseract.image_to_string returns a Python str (unicode)
                ocr_kwargs = {}
                if tesseract_lang:
                    ocr_kwargs['lang'] = tesseract_lang
                if tesseract_config is not None:
                    # empty string is OK; pytesseract accepts config=''
                    ocr_result = pytesseract.image_to_string(img, config=tesseract_config, **ocr_kwargs)
                else:
                    ocr_result = pytesseract.image_to_string(img, **ocr_kwargs)
            except Exception as e:
                # If pytesseract failed for some reason, record note and skip to comments
                note = f' pytesseract failed: {e!r}'
                ocr_result = ''
            if ocr_result and ocr_result.strip():
                # We got OCR text; convert encoding to target and return
                final_text, used_enc = _convert_to_target(ocr_result, target_encoding)
                raw_text = ocr_result
                raw_enc = used_enc
                source = 'ocr'
                return final_text, {
                    'source': source,
                    'raw_encoding': raw_enc,
                    'raw_text': raw_text,
                    'note': note
                }

            # 2) OCR produced nothing usable -> try image comments/metadata
            comments = _extract_image_comments(img)
    except FileNotFoundError:
        return '', {
            'source': 'none',
            'raw_encoding': None,
            'raw_text': None,
            'note': f'File not found: {image_path}'
        }
    except Exception as e:
        return '', {
            'source': 'none',
            'raw_encoding': None,
            'raw_text': None,
            'note': f'Failed opening/processing image: {e!r}'
        }

    # Process any found comments (prefer EXIF UserComment or ImageDescription if present)
    if comments:
        # Preferred tag order
        preferred_tags = ('exif:UserComment', 'exif:ImageDescription',
                          'exif:XPComment', 'exif:XPTitle', 'info:Comment',
                          'jpeg:comment')

        # Try to find a preferred one first
        chosen = None
        for pref in preferred_tags:
            for k, v in comments:
                if k == pref:
                    chosen = (k, v)
                    break
            if chosen:
                break

        # If none of the preferred tags, just take the first non-empty comment
        if not chosen:
            for k, v in comments:
                if v is not None and (not (isinstance(v, str) and not v.strip())):
                    chosen = (k, v)
                    break

        if chosen:
            k, v = chosen
            # Special handling for EXIF UserComment (first 8 bytes indicate encoding)
            if k == 'exif:UserComment' and isinstance(v, (bytes, bytearray)):
                # EXIF UserComment typically begins with an 8-byte code like:
                # b'ASCII\x00\x00\x00' or b'UNICODE\x00' or b'JIS\x00\x00\x00\x00'
                header = bytes(v[:8])
                body = bytes(v[8:])  # actual comment bytes
                try:
                    if header.startswith(b'ASCII'):
                        raw_text = body
                        raw_enc = 'ascii'
                    elif header.startswith(b'UNICODE') or header.startswith(b'UTF'):
                        # Usually UTF-16
                        raw_text = body
                        raw_enc = 'utf-16'
                    elif header.startswith(b'JIS'):
                        raw_text = body
                        raw_enc = 'shift_jis'
                    else:
                        # Unknown header -> treat whole value as bytes
                        raw_text = bytes(v)
                        raw_enc = None
                except Exception:
                    raw_text = bytes(v)
                    raw_enc = None
            else:
                raw_text = v
                raw_enc = None

            final_text, used_enc = _convert_to_target(raw_text, target_encoding)
            # If used_enc wasn't set by convert function but we had a hint, use it
            if not used_enc and raw_enc:
                used_enc = raw_enc

            source = 'comment'
            return final_text, {
                'source': source,
                'raw_encoding': used_enc,
                'raw_text': raw_text,
                'note': note
            }

    # If we got here, neither OCR nor comments returned usable text
    return '', {
        'source': 'none',
        'raw_encoding': None,
        'raw_text': None,
        'note': note or 'No text found via OCR or image metadata/comments.'
    }
