Here is a self-contained Python function that uses pytesseract to OCR an image file, normalizes/decodes the extracted text to a Unicode string (UTF-8), and — if OCR returns nothing useful — falls back to extracting textual comments stored in the image (EXIF/UserComment, XP* tags, PNG text chunks, etc.). The function has an optional flag to return whether the text came from OCR or from image comments.

Copy/paste and use (requires Pillow and pytesseract; chardet is optional but recommended for more robust encoding detection).

```python
from typing import Tuple, Union
from PIL import Image, ExifTags
import pytesseract

# Optional: better encoding detection if available
try:
    import chardet
except Exception:
    chardet = None


def _decode_bytes_to_str(b: Union[bytes, bytearray]) -> str:
    """Decode bytes to Python str using a set of sensible fallbacks."""
    if not b:
        return ""
    # Common EXIF UserComment prefix (8 bytes) per EXIF spec
    try:
        if b.startswith(b'ASCII\0\0\0'):
            return b[8:].split(b'\x00', 1)[0].decode('ascii', errors='replace')
        if b.startswith(b'UNICODE\0'):
            # Usually UTF-16
            return b[8:].decode('utf-16', errors='replace')
    except Exception:
        pass

    # Check BOMs
    if b.startswith(b'\xff\xfe') or b.startswith(b'\xfe\xff'):
        try:
            return b.decode('utf-16', errors='replace')
        except Exception:
            pass
    if b.startswith(b'\xef\xbb\xbf'):
        try:
            return b.decode('utf-8', errors='replace')
        except Exception:
            pass

    # Try utf-8, then utf-16-le (XP* tags), then latin-1
    for enc in ('utf-8', 'utf-16le', 'utf-16', 'latin-1'):
        try:
            return b.decode(enc, errors='replace')
        except Exception:
            continue

    # If chardet is available, try it
    if chardet is not None:
        try:
            det = chardet.detect(b)
            enc = det.get('encoding')
            if enc:
                return b.decode(enc, errors='replace')
        except Exception:
            pass

    # Last resort: decode as latin-1 (direct byte->unicode mapping)
    return b.decode('latin-1', errors='replace')


def _value_to_str(val) -> str:
    """
    Convert various EXIF / PNG info value types (bytes, tuple of ints, str, etc.)
    to a Python str.
    """
    if val is None:
        return ""
    if isinstance(val, str):
        return val
    if isinstance(val, (bytes, bytearray)):
        return _decode_bytes_to_str(bytes(val))
    # Some EXIF fields come as tuples/lists of integers (e.g., XP* fields)
    if isinstance(val, (tuple, list)):
        try:
            b = bytes(val)
            return _decode_bytes_to_str(b)
        except Exception:
            # fallback to joining stringified parts
            return " ".join(str(x) for x in val)
    # fallback
    try:
        return str(val)
    except Exception:
        return ""


def extract_text_from_image(image_path: str,
                            lang: str = 'eng',
                            config: str = '',
                            return_source: bool = False) -> Union[str, Tuple[str, str]]:
    """
    Open an image file, extract text using pytesseract, normalize the encoding to a
    Python str (UTF-8 logical), and if OCR yields no useful text, attempt to get
    textual comments from the image metadata (EXIF / PNG text chunks).

    Parameters:
    - image_path: path to the image file
    - lang: language code(s) for pytesseract (default 'eng')
    - config: optional tesseract config string (e.g. '--psm 6')
    - return_source: if True, return a tuple (text, source) where source is one of
                     'ocr' or 'comment'. If False, return only the text.

    Returns:
    - text (str) or (text, source) if return_source True

    Notes:
    - Requires Pillow (PIL) and pytesseract.
    - Installing chardet is optional for better encoding detection of binary comments.
    """
    # Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise IOError(f"Cannot open image '{image_path}': {e}")

    # 1) Try OCR using pytesseract
    try:
        ocr_text = pytesseract.image_to_string(img, lang=lang, config=config)
    except Exception as e:
        # If pytesseract raises (e.g., tesseract not installed), surface the error
        raise RuntimeError(f"pytesseract failed: {e}")

    # Normalize OCR text: ensure it's a Python str; remove BOM if present; strip only trailing whitespace
    if isinstance(ocr_text, (bytes, bytearray)):
        ocr_text = _decode_bytes_to_str(bytes(ocr_text))
    else:
        # strip UTF-8 BOM if present at start
        if ocr_text.startswith('\ufeff'):
            ocr_text = ocr_text.lstrip('\ufeff')

    # If OCR produced visible text, return it
    if ocr_text and ocr_text.strip():
        if return_source:
            return ocr_text, 'ocr'
        return ocr_text

    # 2) Fallback: inspect image metadata/INFO for textual comments
    comment_candidates = []

    # 2a) EXIF tags (JPEG/TIFF)
    try:
        exif = None
        # PIL has getexif on newer versions, older use _getexif
        if hasattr(img, "getexif"):
            exif = img.getexif()
            # getexif() returns an Exif object that behaves like dict of tag->value
            if exif:
                items = exif.items()
            else:
                items = []
        else:
            # older method
            exif = getattr(img, "_getexif", None)
            if callable(exif):
                exif = exif() or {}
                items = exif.items()
            else:
                items = []
        # Map numeric tag ids to tag names
        for tag_id, val in items:
            tag = ExifTags.TAGS.get(tag_id, tag_id)
            if tag in ('UserComment', 'ImageDescription', 'XPComment', 'XPTitle', 'XPAuthor', 'XPKeywords'):
                candidate = _value_to_str(val)
                if candidate and candidate.strip():
                    comment_candidates.append(candidate)
    except Exception:
        # ignore EXIF read errors
        pass

    # 2b) PNG and other PIL info dictionary (contains text chunks for PNG, 'comment' for some formats)
    try:
        info = getattr(img, "info", {})
        if isinstance(info, dict):
            # common keys: 'comment', 'Description', 'Text', or arbitrary text keys
            for key, val in info.items():
                # val might be str or bytes
                # skip if clearly empty
                if val is None:
                    continue
                candidate = _value_to_str(val)
                if candidate and candidate.strip():
                    comment_candidates.append(candidate)
    except Exception:
        pass

    # 2c) If no direct EXIF/INFO, try to find any textual-looking metadata in exif tags loop (already done).
    # If we still have nothing, return empty string.
    final_comment = ""
    if comment_candidates:
        # Prefer the first non-empty candidate; you may join them if desired
        # Join with newlines but strip each
        final_comment = "\n".join(c.strip() for c in comment_candidates if c and c.strip())

    if final_comment:
        if return_source:
            return final_comment, 'comment'
        return final_comment

    # Nothing found anywhere, return empty string
    if return_source:
        return "", "none"
    return ""
```

