- Installing chardet (pip install chardet) improves guessing of unknown encodings in binary comment fields.

def fetch_github_repo_info(api_url, token=None, timeout=10, issues_warning_threshold=100):
    """
    Fetch and return GitHub repository information from a GitHub API repository URL.

    Parameters:
      - api_url (str): Full GitHub API repo URL, e.g. "https://api.github.com/repos/owner/repo"
      - token (str|None): Optional GitHub personal access token to increase rate limits / access private repos.
      - timeout (float): Request timeout in seconds.
      - issues_warning_threshold (int): If repository's open_issues_count exceeds this, a warning will be printed.

    Returns:
      - dict: Parsed JSON repository data on success.
      - None: On failure (errors are printed).

    Notes:
      - Uses the `requests` library. Ensure it's installed: pip install requests
      - The "open_issues_count" includes pull requests as well as issues.
    """
    import requests
    from datetime import datetime

    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "fetch-github-repo-info/1.0"
    }
    if token:
        headers["Authorization"] = f"token {token}"

    try:
        resp = requests.get(api_url, headers=headers, timeout=timeout)
    except requests.exceptions.RequestException as exc:
        print(f"Network/request error while trying to reach {api_url}: {exc}")
        return None

    # Try to parse JSON body if present
    try:
        data = resp.json()
    except ValueError:
        data = None

    status = resp.status_code

    # Helper to parse rate-limit reset header
    def _parse_reset(ts):
        try:
            t = int(ts)
            return datetime.utcfromtimestamp(t).strftime("%Y-%m-%d %H:%M:%S UTC")
        except Exception:
            return ts

    # Handle specific HTTP statuses and rate limiting
    if status == 200:
        # Successful request
        if isinstance(data, dict):
            open_issues = data.get("open_issues_count")
            if isinstance(open_issues, int) and open_issues > issues_warning_threshold:
                print(
                    f"Warning: repository reports {open_issues} open issues (threshold: {issues_warning_threshold})."
                    " This may indicate a high maintenance backlog or many PRs counted as issues."
                )
        return data

    # Rate limit / abuse cases
    if status in (403, 429):
        remaining = resp.headers.get("X-RateLimit-Remaining")
        reset = resp.headers.get("X-RateLimit-Reset")
        retry_after = resp.headers.get("Retry-After")

        # GitHub typical rate-limit exceeded indicator
        msg = None
        if isinstance(data, dict):
            msg = data.get("message")

        if (remaining == "0") or (msg and "rate limit exceeded" in msg.lower()) or status == 429:
            reset_readable = _parse_reset(reset) if reset else "unknown"
            if retry_after:
                print(f"Rate limit reached. Retry after {retry_after} seconds. Reset at: {reset_readable}")
            else:
                print(f"API rate limit exceeded. Limit resets at: {reset_readable}")
            return None

        # Other 403 case (e.g., forbidden)
        if msg:
            print(f"Access forbidden (403): {msg}")
        else:
            print("Access forbidden (403).")
        return None

    # Authentication issues
    if status == 401:
        if isinstance(data, dict) and data.get("message"):
            print(f"Unauthorized (401): {data.get('message')}")
        else:
            print("Unauthorized (401). Check your token or credentials.")
        return None

    # Not found
    if status == 404:
        if isinstance(data, dict) and data.get("message"):
            print(f"Not found (404): {data.get('message')}")
        else:
            print(f"Repository not found at {api_url} (404).")
        return None

    # Server errors
    if 500 <= status < 600:
        print(f"Server error ({status}). Try again later.")
        if isinstance(data, dict) and data.get("message"):
            print("Server message:", data.get("message"))
        return None

    # Generic HTTP error fallback
    # Try to show any message returned by the API
    if isinstance(data, dict) and data.get("message"):
        print(f"HTTP error {status}: {data.get('message')}")
    else:
        print(f"HTTP error {status} while fetching {api_url}.")
    return None

