Below is a single self-contained Python function that meets your requirements. It uses pandas to read the CSV, a robust converter to turn string numbers with commas (including both thousands separators and decimal-comma formats) into floats, computes mean and standard deviation for each detected numerical column, generates histogram plots (optionally saving them), and runs a one-way ANOVA across numerical columns (when there are at least two valid columns). It also uses scikit-learn (SimpleImputer) optionally to impute missing values for plotting/ANOVA if you request imputation.

Copy-paste and run the function in a Python environment with pandas, numpy, matplotlib, scipy, and scikit-learn installed.

```
def analyze_csv_numerical(
    csv_path,
    delimiter=',',
    output_dir=None,
    show_plots=True,
    impute_missing=False,
    convert_threshold=0.5,
    figsize=(8, 5)
):
    """
    Analyze numerical data from a CSV file.

    Steps:
    - Read CSV (as strings).
    - Convert string representations of numbers that may use commas
      (thousands separators or decimal commas) into floats.
    - Detect numerical columns (columns where at least `convert_threshold`
      fraction of values converted to numbers).
    - Compute mean and standard deviation for each detected numeric column.
    - Generate and show/save a histogram for each numeric column.
    - Perform a one-way ANOVA test across the numeric columns (if 2+ valid columns).
      By default ANOVA uses the raw non-imputed numeric values. Set impute_missing=True
      to fill NaNs (SimpleImputer mean) before ANOVA/plots.

    Parameters:
    - csv_path: path to CSV file
    - delimiter: CSV delimiter (default ',')
    - output_dir: if provided, histogram PNGs will be saved into this directory.
    - show_plots: if True, display histograms (requires interactive backend)
    - impute_missing: if True, missing numeric values are imputed (mean) before histograms/ANOVA
    - convert_threshold: fraction (0-1) minimum convertible entries for a column to be considered numeric
    - figsize: size for histogram figures

    Returns:
    A dict with:
      - 'numeric_columns': list of detected numeric column names
      - 'stats': dict mapping column -> {'mean': ..., 'std': ..., 'count': ...}
      - 'hist_files': dict mapping column -> filename or None if only shown
      - 'anova': {'F': ..., 'p': ...} or message explaining why ANOVA not run
    """
    import os
    import re
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    from sklearn.impute import SimpleImputer
    from scipy import stats

    # Helper: robust converter for strings like "1,234.56", "1.234,56", "1234,56", "1,234"
    def _clean_numeric_string(s):
        if pd.isna(s):
            return np.nan
        if not isinstance(s, str):
            # leave numbers as-is
            return s
        s = s.strip()
        if s == '':
            return np.nan
        # remove currency symbols, spaces, non-digit except . , - e E
        s = re.sub(r'[^\d\-\+eE\.,]', '', s)
        if s == '':
            return np.nan

        # If contains both '.' and ','
        if '.' in s and ',' in s:
            # whichever sep occurs last is likely the decimal separator
            if s.rfind(',') > s.rfind('.'):
                # comma is decimal -> remove dots (thousands), replace comma with dot
                s2 = s.replace('.', '').replace(',', '.')
            else:
                # dot is decimal -> remove commas (thousands)
                s2 = s.replace(',', '')
            try:
                return float(s2)
            except:
                return np.nan

        # Only comma present
        if ',' in s and '.' not in s:
            parts = s.split(',')
            # if last part has length 3 -> likely thousands separators -> remove all commas
            if len(parts[-1]) == 3:
                s2 = s.replace(',', '')
                try:
                    return float(s2)
                except:
                    # fall back to treating comma as decimal
                    s2 = s.replace(',', '.')
                    try:
                        return float(s2)
                    except:
                        return np.nan
            else:
                # treat comma as decimal separator
                s2 = s.replace(',', '.')
                try:
                    return float(s2)
                except:
                    return np.nan

        # Only dot present
        if '.' in s and ',' not in s:
            parts = s.split('.')
            # maybe dot is thousands sep if last part has length 3
            if len(parts[-1]) == 3 and len(parts) > 1:
                s2 = s.replace('.', '')
                try:
                    return float(s2)
                except:
                    return np.nan
            else:
                try:
                    return float(s)
                except:
                    return np.nan

        # No separators, just digits / maybe signs
        try:
            return float(s)
        except:
            return np.nan

    # Read CSV as strings to control conversions
    df_raw = pd.read_csv(csv_path, sep=delimiter, dtype=str)
    nrows, ncols = df_raw.shape

    converted = {}
    numeric_columns = []
    numeric_df = pd.DataFrame(index=df_raw.index)  # will contain floats for numeric columns

    # Try converting each column
    for col in df_raw.columns:
        series = df_raw[col].astype(object)  # keep strings
        # apply converter
        converted_series = series.map(_clean_numeric_string)
        # coerce to numeric (float)
        converted_series = pd.to_numeric(converted_series, errors='coerce')
        n_non_na = converted_series.notna().sum()
        frac = n_non_na / max(1, nrows)
        converted[col] = {
            'converted': converted_series,
            'non_na_count': int(n_non_na),
            'frac': frac
        }
        # decide numeric if enough conversion
        if frac >= convert_threshold and n_non_na >= 1:
            numeric_columns.append(col)
            numeric_df[col] = converted_series

    # Prepare results
    stats_dict = {}
    hist_files = {}
    # Optionally impute missing values for plotting/ANOVA
    numeric_for_analysis = numeric_df.copy()
    if impute_missing and not numeric_df.empty:
        imp = SimpleImputer(strategy='mean')
        # SimpleImputer returns numpy array
        imputed_arr = imp.fit_transform(numeric_df.values)
        numeric_for_analysis = pd.DataFrame(imputed_arr, columns=numeric_df.columns, index=numeric_df.index)

    # Compute stats based on the original numeric_df (not imputed) to avoid masking NaNs
    for col in numeric_columns:
        colvals = numeric_df[col].dropna()
        mean_val = float(colvals.mean()) if len(colvals) > 0 else float('nan')
        std_val = float(colvals.std(ddof=1)) if len(colvals) > 1 else float('nan')
        stats_dict[col] = {'mean': mean_val, 'std': std_val, 'count': int(len(colvals))}

        # Plot histogram (use imputed data if requested to fill gaps for plotting)
        plot_series = numeric_for_analysis[col].dropna() if not impute_missing else numeric_for_analysis[col]
        plt.figure(figsize=figsize)
        plt.hist(plot_series, bins='auto', alpha=0.7, edgecolor='black')
        plt.title(f'{col}  (mean={stats_dict[col]["mean"]:.4g}, std={stats_dict[col]["std"]:.4g}, n={stats_dict[col]["count"]})')
        plt.xlabel(col)
        plt.ylabel('Frequency')
        plt.tight_layout()

        if output_dir:
            os.makedirs(output_dir, exist_ok=True)
            # sanitize filename
            safe_col = re.sub(r'[^\w\-_\. ]', '_', col)
            fname = os.path.join(output_dir, f'hist_{safe_col}.png')
            plt.savefig(fname)
            hist_files[col] = fname
            if not show_plots:
                plt.close()
            else:
                plt.show()
        else:
            hist_files[col] = None
            if show_plots:
                plt.show()
            else:
                plt.close()

    # ANOVA: require at least two numeric columns with >1 observations
    anova_result = None
    valid_anova_cols = []
    for col in numeric_columns:
        arr = numeric_df[col].dropna().values
        if len(arr) > 1:
            valid_anova_cols.append(col)

    if len(valid_anova_cols) < 2:
        anova_result = {'message': 'ANOVA not run: need at least two numeric columns with >=2 observations each.'}
    else:
        try:
            # Build arrays for ANOVA. If impute_missing requested, use numeric_for_analysis (which has no NaNs)
            if impute_missing:
                arrays = [numeric_for_analysis[col].values for col in valid_anova_cols]
            else:
                arrays = [numeric_df[col].dropna().values for col in valid_anova_cols]
            fstat, pval = stats.f_oneway(*arrays)
            anova_result = {'F': float(fstat), 'p': float(pval), 'columns': valid_anova_cols}
        except Exception as e:
            anova_result = {'message': f'ANOVA failed: {e}'}

    return {
        'numeric_columns': numeric_columns,
        'stats': stats_dict,
        'hist_files': hist_files,
        'anova': anova_result,
        'converted_overview': {col: {'non_na_count': converted[col]['non_na_count'], 'frac': converted[col]['frac']} for col in df_raw.columns}
    }
```

Usage example:
- To read "data.csv", show plots and save histograms to "plots/" directory:
  results = analyze_csv_numerical("data.csv", output_dir="plots", show_plots=True)

- To impute missing numeric values before ANOVA/plotting:
  results = analyze_csv_numerical("data.csv", impute_missing=True)

Returned results contain per-column means/stds and ANOVA results including F and p-value.

Here is a self-contained Python function that uses requests and BeautifulSoup (bs4). It fetches the URL, finds all <script> tags, extracts brace-delimited object literals from their text, and attempts to evaluate each as a Python dict using several safe-ish strategies (ast.literal_eval, json.loads, and a best-effort JS-to-Python boolean/null replacement). It returns a list of successfully parsed dicts.

Note: evaluating arbitrary text can be risky; this function avoids plain eval and uses ast.literal_eval and json.loads where possible. It still performs heuristic transformations which may silently fail for malformed JS. Install required packages if needed (pip install requests bs4).

def fetch_and_extract_dicts(url, timeout=10, headers=None):
    """
    Fetch the page at `url`, parse <script> tags with BeautifulSoup, and attempt to
    extract and evaluate any brace-delimited object literals found within script text as Python dicts.

    Returns:
      list of dict objects successfully parsed from script contents (may be empty).

    Parameters:
      url (str): the webpage URL to fetch
      timeout (int/float): requests timeout in seconds
      headers (dict): optional requests headers (e.g., {'User-Agent': '...'})
    """
    import requests
    from bs4 import BeautifulSoup
    import ast
    import json

    if headers is None:
        headers = {
            "User-Agent": "python-requests/bs4-extractor"
        }

    try:
        resp = requests.get(url, timeout=timeout, headers=headers)
        resp.raise_for_status()
        text = resp.text
    except Exception as e:
        raise RuntimeError(f"Error fetching URL {url!r}: {e}")

    soup = BeautifulSoup(text, "html.parser")
    scripts = soup.find_all("script")

    def find_braced_substrings(s):
        """Return list of substrings in s that are balanced {...} objects (top-level)."""
        results = []
        stack = []
        start = None
        for i, ch in enumerate(s):
            if ch == "{":
                if not stack:
                    start = i
                stack.append("{")
            elif ch == "}":
                if stack:
                    stack.pop()
                    if not stack and start is not None:
                        results.append(s[start:i + 1])
                        start = None
        return results

    parsed_dicts = []
    seen = set()  # avoid duplicates by canonical repr

    for idx, tag in enumerate(scripts):
        script_text = tag.string
        # if tag.string is None, try getting full text (handles comments, CDATA, etc.)
        if script_text is None:
            script_text = tag.get_text(separator=" ", strip=False)
        if not script_text:
            continue

        candidates = find_braced_substrings(script_text)
        # if none found but script contains only a JSON object (no outer braces? unlikely),
        # also try the whole trimmed text as a candidate
        if not candidates:
            stripped = script_text.strip()
            if stripped.startswith("{") and stripped.endswith("}"):
                candidates = [stripped]

        for cand in candidates:
            # Try several safe parsing strategies in order
            parsed = None

            # 1) Try ast.literal_eval directly (works for Python-style dict literals,
            #    including single-quoted strings and Python True/False/None)
            try:
                val = ast.literal_eval(cand)
                if isinstance(val, dict):
                    parsed = val
            except Exception:
                pass

            # 2) Try json.loads (works for proper JSON)
            if parsed is None:
                try:
                    val = json.loads(cand)
                    if isinstance(val, dict):
                        parsed = val
                except Exception:
                    pass

            # 3) Try lightweight JS -> Python replacements (true/false/null -> True/False/None)
            #    then use ast.literal_eval. This may catch many JS object literals using single quotes
            if parsed is None:
                # Replace only unquoted true/false/null using simple token replacements.
                # This is heuristic and may alter data inside strings; it's a best-effort attempt.
                cand2 = cand
                cand2 = cand2.replace(": true", ": True").replace(":false", ": False")  # partial
                # broader replacements (may affect inside strings)
                cand2 = cand2.replace(" true", " True").replace(" false", " False").replace(" null", " None")
                try:
                    val = ast.literal_eval(cand2)
                    if isinstance(val, dict):
                        parsed = val
                except Exception:
                    pass

            if parsed is not None:
                key = repr(parsed)
                if key not in seen:
                    parsed_dicts.append(parsed)
                    seen.add(key)

    return parsed_dicts

Example usage:
- dicts = fetch_and_extract_dicts("https://example.com/page-with-js")
- The function returns a list of dictionaries found in script tags.

import re
import requests
from bs4 import BeautifulSoup

def extract_url_and_get_title(text: str, timeout: float = 10.0) -> str:
    """
    Extract the first URL from `text`, fetch the page, and return its title.
    If no URL is found or fetching/parsing fails, returns an error message string.

    Returns:
      - On success: the page title (string).
      - On failure: an error message starting with "Error:".
    """
    # Basic URL extraction (http(s) or www.)
    url_re = re.compile(r'(https?://[^\s"\'<>]+|www\.[^\s"\'<>]+)', flags=re.IGNORECASE)
    m = url_re.search(text)
    if not m:
        return "Error: No valid URL found in input."

    url = m.group(0)
    if url.startswith("www."):
        url = "http://" + url  # assume http if scheme missing

    # Fetch the page
    headers = {"User-Agent": "Mozilla/5.0 (compatible; Bot/1.0)"}
    try:
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
        resp.raise_for_status()
    except requests.exceptions.RequestException as e:
        return f"Error: Failed to fetch URL '{url}': {e}"

    # Parse HTML and extract title
    try:
        soup = BeautifulSoup(resp.text, "html.parser")
    except Exception as e:
        return f"Error: Failed to parse HTML from '{url}': {e}"

    # 1) Try <title>
    title = None
    if soup.title and soup.title.string:
        title = soup.title.string.strip()

    # 2) Try common meta tags (og:title, twitter:title)
    if not title:
        for attr in (("property", "og:title"), ("name", "og:title"),
                     ("property", "twitter:title"), ("name", "twitter:title")):
            meta = soup.find("meta", attrs={attr[0]: attr[1]})
            if meta and meta.get("content"):
                title = meta["content"].strip()
                break

    # 3) Fallback: first <h1>
    if not title:
        h1 = soup.find("h1")
        if h1:
            text_h1 = h1.get_text(strip=True)
            if text_h1:
                title = text_h1

    if title:
        return title
    return f"Error: No title found at URL '{url}'."

import re
import requests
from bs4 import BeautifulSoup

def extract_title_from_text(text, timeout=10):
    """
    Extract the first URL found in the input text and return the web page title.
    Returns a dict with either:
      {'status': 'ok', 'title': '<page title>', 'url': '<resolved url>'}
    or
      {'status': 'error', 'message': '<explanation>'}

    Requirements:
      - bs4 (BeautifulSoup) and requests must be installed.

    Behavior:
      - Looks first for explicit http/https or www URLs.
      - If none found, tries to find a bare domain-like token (e.g. example.com) and prepends http://.
      - Strips trailing punctuation commonly attached to URLs in text.
      - Fetches the URL with a simple User-Agent and timeout.
      - Ensures response is an HTML document and extracts the <title>.
    """
    if not text or not isinstance(text, str):
        return {'status': 'error', 'message': 'Input must be a non-empty string.'}

    # 1) Try to find a URL with scheme or starting with www.
    url_pattern = re.compile(r'(?:(?:https?://)|www\.)[^\s<>")\]\}]+', re.IGNORECASE)
    m = url_pattern.search(text)

    # 2) Fallback: look for bare domain-like tokens (e.g. example.com/path)
    if not m:
        # avoid matching emails by negative lookbehind for @
        bare_domain_pattern = re.compile(r'(?<!@)\b([A-Za-z0-9-]+\.[A-Za-z]{2,})(/[^\s<>")\]\}]*)?', re.IGNORECASE)
        m = bare_domain_pattern.search(text)

    if not m:
        return {'status': 'error', 'message': 'No valid URL found in the provided text.'}

    raw_url = m.group(0).strip()

    # Remove trailing punctuation commonly attached to URLs in running text
    raw_url = raw_url.rstrip('.,;:!?)"\']')

    # Normalize: add scheme if missing
    if not re.match(r'^https?://', raw_url, re.IGNORECASE):
        raw_url = 'http://' + raw_url

    # Simple HTTP GET with timeout and a User-Agent
    headers = {'User-Agent': 'Mozilla/5.0 (compatible; url-title-extractor/1.0)'}
    try:
        resp = requests.get(raw_url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return {'status': 'error', 'message': f'Failed to fetch URL: {e}'}

    # Check for successful response
    if resp.status_code < 200 or resp.status_code >= 400:
        return {'status': 'error', 'message': f'HTTP request failed with status code {resp.status_code}.'}

    # Check content type for HTML
    content_type = resp.headers.get('Content-Type', '')
    if 'html' not in content_type.lower():
        return {'status': 'error', 'message': f'URL did not return an HTML document (Content-Type: {content_type}).'}

    # Parse HTML and extract title
    try:
        soup = BeautifulSoup(resp.text, 'html.parser')
        title_tag = soup.find('title')
        if not title_tag:
            return {'status': 'error', 'message': 'HTML page contains no <title> element.'}
        title = title_tag.get_text(strip=True)
        if not title:
            return {'status': 'error', 'message': 'Title element is empty.'}
        return {'status': 'ok', 'title': title, 'url': resp.url}
    except Exception as e:
        return {'status': 'error', 'message': f'Failed to parse HTML: {e}'}

import re
import requests
from bs4 import BeautifulSoup

def get_title_from_text(text, timeout=10):
    """
    Extract the first URL found in `text`, fetch the page, and return its <title>.
    Returns an error message string if no valid URL is found or the page couldn't be fetched/parsed.

    Parameters:
    - text (str): input string possibly containing a URL
    - timeout (int or float): request timeout in seconds (default 10)

    Returns:
    - str: page title on success, or an error message beginning with "Error:" on failure

    Example:
    >>> get_title_from_text("Check this out: https://example.com.")
    'Example Domain'
    """
    if not isinstance(text, str):
        return "Error: Input must be a string."

    # Find first URL (http(s) or www)
    pattern = re.compile(r'(https?://[^\s<>"]+|www\.[^\s<>"]+)', re.IGNORECASE)
    match = pattern.search(text)
    if not match:
        return "Error: No URL found in input."

    url = match.group(0).rstrip('.,;!?)"\']')  # strip common trailing punctuation
    if url.startswith('www.'):
        url = 'http://' + url  # add scheme if missing

    try:
        headers = {'User-Agent': 'Mozilla/5.0 (compatible; TitleFetcher/1.0)'}
        resp = requests.get(url, timeout=timeout, headers=headers, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return f"Error: Failed to fetch URL: {e}"

    if resp.status_code != 200:
        return f"Error: Request returned status code {resp.status_code}."

    content_type = resp.headers.get('Content-Type', '')
    if 'html' not in content_type.lower():
        return f"Error: URL does not point to an HTML page (Content-Type: {content_type})."

    try:
        soup = BeautifulSoup(resp.text, 'html.parser')

        # Primary: <title>
        if soup.title and soup.title.string:
            title = soup.title.string.strip()
            if title:
                return title

        # Fallbacks: og:title, meta[name=title], first h1
        og = soup.find('meta', property='og:title')
        if og and og.get('content'):
            return og.get('content').strip()

        meta_title = soup.find('meta', attrs={'name': 'title'})
        if meta_title and meta_title.get('content'):
            return meta_title.get('content').strip()

        h1 = soup.find('h1')
        if h1:
            h1_text = h1.get_text(strip=True)
            if h1_text:
                return h1_text

        return "Error: No title found in the page."
    except Exception as e:
        return f"Error: Failed to parse HTML: {e}"
